        if(info[id] == 0)
            info[id] = j + 1;
        M[loc] = t;
        res[id] = 0;
    }
    else
    {
        M[loc] = sqrt(t);  // Result is real
        res[id] = 1 / M[loc];  // Reciprocal is real
    }
}

